function completeDictionaries(){const out=baseDictionaries();for(const [key,...values] of rows(extra+'\n'+finalCopy))ids.forEach((id,i)=>out[id][key]=values[i]);const aliases={'Compare material directions':'Compare two material directions','Material and process guide':'Material & process guide','Requested shipment':'Requested shipment / departure','Requested receipt':'Requested arrival / receipt','standard':'Standard','custom':'Custom','✓ Copied. Text only — attach files separately. No email sent.':'? Copied. Text only — attach files separately. No email sent.'};for(const dict of Object.values(out))for(const [key,original]of Object.entries(aliases))dict[key]=(dict[original]||original).replace(/^\? /,'✓ ');return out;}
module.exports={ids,dictionaries:()=>{const out={...completeDictionaries(),'zh-tw':Object.fromEntries(chinese.trim().split('\n').map(line=>line.split('|')))};for(const [id,copy]of Object.entries(require('./product-copy')()))Object.assign(out[id],copy);return out;}};
